import { useTranslate } from "../../../i18n/use-translate";
import type { HeartRateZone } from "../../../types/profile";
import { type ZonePair, zonePairRange } from "./hr-zone-range";

type TargetHrZoneRangeSummaryProps = {
  zones: Array<HeartRateZone>;
  pair: ZonePair | null;
  error: string;
};

export const TargetHrZoneRangeSummary = ({
  zones,
  pair,
  error,
}: TargetHrZoneRangeSummaryProps) => {
  const t = useTranslate("targets");
  const range = pair ? zonePairRange(zones, pair.fromZone, pair.toZone) : null;

  return (
    <>
      {pair && range && (
        <p className="text-sm text-gray-600 dark:text-gray-400">
          {t("zoneRange.summary", {
            from: `Z${pair.fromZone}`,
            to: `Z${pair.toZone}`,
            min: range.min,
            max: range.max,
          })}
        </p>
      )}
      {error && (
        <p className="text-sm text-danger-text" role="alert">
          {error}
        </p>
      )}
    </>
  );
};
