import { GripVertical } from "lucide-react";
import type { HTMLAttributes } from "react";

import { useTranslate } from "../../../i18n/use-translate";
import { Tooltip } from "../../atoms/Tooltip/Tooltip";

export type DragHandleProps = HTMLAttributes<HTMLDivElement> & {
  isDragging?: boolean;
};

export const DragHandle = ({
  isDragging = false,
  className = "",
  ...props
}: DragHandleProps) => {
  const t = useTranslate("editor");
  const baseClasses =
    "absolute left-0 top-1/2 -translate-y-1/2 cursor-grab active:cursor-grabbing touch-none min-h-[44px] min-w-[44px] flex items-center justify-center rounded transition-colors hover:bg-surface-elevated";
  const colorClasses = isDragging
    ? "text-ink-strong"
    : "text-neutral-400 hover:text-neutral-600 dark:text-neutral-500 dark:hover:text-neutral-300";
  const classes = [baseClasses, colorClasses, className]
    .filter(Boolean)
    .join(" ");

  return (
    <Tooltip content={t("stepCard.dragTooltip")} side="left">
      <div
        className={classes}
        aria-label={t("stepCard.dragAria")}
        data-testid="drag-handle"
        {...props}
      >
        <GripVertical size={20} aria-hidden="true" />
      </div>
    </Tooltip>
  );
};
