import { useEffect } from "react";

import { useTranslate } from "../../../i18n/use-translate";
import type { Target } from "../../../types/krd";
import type { HeartRateZone } from "../../../types/profile";
import { Input } from "../../atoms/Input/Input";
import {
  buildZonePairTarget,
  clampZonePair,
  findZonePair,
  zonePairOptions,
} from "./hr-zone-range";
import { TargetHrZoneRangeSummary } from "./TargetHrZoneRangeSummary";

type TargetHrZoneRangeFieldsProps = {
  zones: Array<HeartRateZone>;
  value: Target | null;
  disabled: boolean;
  error: string;
  onChange: (target: Target | null) => void;
};

export const TargetHrZoneRangeFields = ({
  zones,
  value,
  disabled,
  error,
  onChange,
}: TargetHrZoneRangeFieldsProps) => {
  const t = useTranslate("targets");
  const pair = findZonePair(zones, value);
  const first = zones[0];

  // Entering the mode clears the target; seed it with the first zone so the
  // selects always show a band the step can carry.
  useEffect(() => {
    if (pair || !first) return;
    onChange(buildZonePairTarget(zones, first.zone, first.zone));
  }, [pair, first, zones, onChange]);

  if (!first) {
    return (
      <p className="text-sm text-gray-600 dark:text-gray-400">
        {t("zoneRange.needsZones")}
      </p>
    );
  }

  const options = zonePairOptions(zones, t);

  const pick =
    (side: "from" | "to") => (event: React.ChangeEvent<HTMLSelectElement>) => {
      const picked = Number.parseInt(event.target.value, 10);
      const current = pair ?? { fromZone: picked, toZone: picked };
      const next = clampZonePair(side, picked, current);
      onChange(buildZonePairTarget(zones, next.fromZone, next.toZone));
    };

  return (
    <div className="space-y-3">
      <Input
        variant="select"
        label={t("zoneRange.fromLabel")}
        value={String(pair?.fromZone ?? first.zone)}
        onChange={pick("from")}
        disabled={disabled}
        options={options}
        aria-label={t("zoneRange.fromAria")}
      />
      <Input
        variant="select"
        label={t("zoneRange.toLabel")}
        value={String(pair?.toZone ?? first.zone)}
        onChange={pick("to")}
        disabled={disabled}
        options={options}
        aria-label={t("zoneRange.toAria")}
      />
      <TargetHrZoneRangeSummary zones={zones} pair={pair} error={error} />{" "}
    </div>
  );
};
