import { TargetHrZoneRangeFields } from "./TargetHrZoneRangeFields";
import type { TargetPickerFieldsValueProps } from "./TargetPickerFields.types";
import { TargetPickerRangeFields } from "./TargetPickerRangeFields";
import { TargetValueInput } from "./TargetValueInput";

export function TargetPickerFieldsValue({
  unit,
  targetType,
  targetValue,
  minValue,
  maxValue,
  displayError,
  disabled,
  activeProfile,
  hrZones,
  value,
  onValueChange,
  onMinChange,
  onMaxChange,
  onTargetChange,
  getValueLabel,
  getValuePlaceholder,
  rangeUnit,
}: TargetPickerFieldsValueProps) {
  if (!unit) return null;

  if (unit === "zone_range") {
    return (
      <TargetHrZoneRangeFields
        zones={hrZones}
        value={value}
        disabled={disabled}
        error={displayError}
        onChange={onTargetChange}
      />
    );
  }

  if (unit === "range") {
    return (
      <TargetPickerRangeFields
        clock={targetType === "pace"}
        unit={rangeUnit}
        minValue={minValue}
        maxValue={maxValue}
        displayError={displayError}
        disabled={disabled}
        onMinChange={onMinChange}
        onMaxChange={onMaxChange}
      />
    );
  }

  return (
    <TargetValueInput
      targetType={targetType}
      unit={unit}
      value={targetValue}
      onChange={onValueChange}
      disabled={disabled}
      error={displayError}
      activeProfile={activeProfile}
      getValueLabel={getValueLabel}
      getValuePlaceholder={getValuePlaceholder}
    />
  );
}
