/**
 * StatValue Component
 *
 * Displays a statistic value with optional estimate indicator.
 */

import React from "react";

import { useTranslate } from "../../../i18n/use-translate";

export type StatValueProps = {
  value: string | number | null;
  hasEstimate?: boolean;
  emptyText?: string;
};

export const StatValue: React.FC<StatValueProps> = ({
  value,
  hasEstimate = false,
  emptyText = "—",
}) => {
  const t = useTranslate("workout-detail");
  if (value === null || value === undefined) {
    return <span className="text-ink-muted">{emptyText}</span>;
  }

  return (
    <>
      {value}
      {hasEstimate && (
        <span
          className="ml-1 text-xs text-ink-muted"
          title={t("stats.estimateIndicatorTitle")}
        >
          *
        </span>
      )}
    </>
  );
};
