/**
 * Heart-rate zone pairs.
 *
 * Garmin's "custom heart rate" target is an absolute bpm band. The picker
 * offers the same thing as a pair of athlete zones: the band runs from the
 * first zone's lower bound to the second zone's upper bound, and is stored as
 * a KRD `heart_rate` `range` so every writer (GCN, FIT, TCX) keeps it.
 */

import type { Translate } from "../../../i18n/use-translate";
import type { Target } from "../../../types/krd";
import type { HeartRateZone, Profile, SportKey } from "../../../types/profile";
import { isSportKey } from "../../../types/sport-zones";

const FALLBACK_SPORT: SportKey = "cycling";

/** The zone table a workout uses: its own sport, else cycling. */
export const resolveHrZones = (
  profile: Profile | null | undefined,
  sport?: string
): Array<HeartRateZone> => {
  if (!profile) return [];
  const key = sport && isSportKey(sport) ? sport : FALLBACK_SPORT;
  const config = profile.sportZones[key] ?? profile.sportZones[FALLBACK_SPORT];
  const zones = config?.heartRateZones.zones ?? [];
  return zones
    .filter((zone) => zone.maxBpm > 0)
    .sort((a, b) => a.zone - b.zone);
};

export type HrZoneRange = { min: number; max: number };
export type ZonePair = { fromZone: number; toZone: number };

/** Bpm band covered by two zones, or null when the order is reversed. */
export const zonePairRange = (
  zones: Array<HeartRateZone>,
  fromZone: number,
  toZone: number
): HrZoneRange | null => {
  const from = zones.find((zone) => zone.zone === fromZone);
  const to = zones.find((zone) => zone.zone === toZone);
  if (!from || !to || from.zone > to.zone) return null;
  return { min: from.minBpm, max: to.maxBpm };
};

/** The zone pair a stored bpm range reproduces exactly, if any. */
export const findZonePair = (
  zones: Array<HeartRateZone>,
  value: Target | null
): ZonePair | null => {
  if (!value || value.type !== "heart_rate") return null;
  if (value.value.unit !== "range") return null;
  const { min, max } = value.value;
  const from = zones.find((zone) => zone.minBpm === min);
  const to = [...zones].reverse().find((zone) => zone.maxBpm === max);
  if (!from || !to || from.zone > to.zone) return null;
  return { fromZone: from.zone, toZone: to.zone };
};

/** Select options for the zone-pair pickers, one per athlete zone. */
export const zonePairOptions = (zones: Array<HeartRateZone>, t: Translate) =>
  zones.map((zone) => ({
    value: String(zone.zone),
    label: t("zoneRange.option", {
      zone: zone.zone,
      name: zone.name,
      min: zone.minBpm,
      max: zone.maxBpm,
    }),
  }));

/** Picking one end drags the other along, so the band never inverts. */
export const clampZonePair = (
  side: "from" | "to",
  picked: number,
  current: ZonePair
): ZonePair =>
  side === "from"
    ? { fromZone: picked, toZone: Math.max(picked, current.toZone) }
    : { fromZone: Math.min(picked, current.fromZone), toZone: picked };

export const buildZonePairTarget = (
  zones: Array<HeartRateZone>,
  fromZone: number,
  toZone: number
): Target | null => {
  const range = zonePairRange(zones, fromZone, toZone);
  if (!range) return null;
  return { type: "heart_rate", value: { unit: "range", ...range } };
};
